166	    private BigDecimal applyAdjustments(String procedureCode, BigDecimal base, PricingContext context) {
167	        String family = PROCEDURE_FAMILIES.get(procedureCode);
168	        if (family == null) {
169	            family = deriveFamilyFromCode(procedureCode);
170	        }
171	
172	        BigDecimal adjusted = base;
173	
174	        switch (family) {
175	            case "OFFICE_VISIT_NEW":
176	                if (Boolean.TRUE.equals(context.isFirstVisit())) {
177	                    adjusted = adjusted.multiply(new BigDecimal("1.15"));
178	                }
179	                if (context.getComplexityLevel() != null) {
180	                    switch (context.getComplexityLevel()) {
181	                        case "LOW":
182	                            adjusted = adjusted.multiply(new BigDecimal("0.90"));
183	                            break;
184	                        case "MODERATE":
185	                            break;
186	                        case "HIGH":
187	                            adjusted = adjusted.multiply(new BigDecimal("1.20"));
188	                            break;
189	                        case "VERY_HIGH":
190	                            adjusted = adjusted.multiply(new BigDecimal("1.40"));
191	                            break;
192	                    }
193	                }
194	                break;
195	
196	            case "OFFICE_VISIT_ESTABLISHED":
197	                if (context.getTimeSinceLastVisit() != null) {
198	                    int daysSince = context.getTimeSinceLastVisit();
199	                    if (daysSince < 30) {
200	                        adjusted = adjusted.multiply(new BigDecimal("0.85"));
201	                    } else if (daysSince > 365) {
202	                        adjusted = adjusted.multiply(new BigDecimal("1.10"));
203	                    }
204	                }
205	                if (context.getComplexityLevel() != null) {
206	                    switch (context.getComplexityLevel()) {
207	                        case "LOW":
208	                            adjusted = adjusted.multiply(new BigDecimal("0.85"));
209	                            break;
210	                        case "MODERATE":
211	                            break;
212	                        case "HIGH":
213	                            adjusted = adjusted.multiply(new BigDecimal("1.25"));
214	                            break;
215	                        case "VERY_HIGH":
216	                            adjusted = adjusted.multiply(new BigDecimal("1.50"));
217	                            break;
218	                    }
219	                }
220	                break;
221	
222	            case "RADIOLOGY":
223	                if (Boolean.TRUE.equals(context.isPortable())) {
224	                    adjusted = adjusted.multiply(new BigDecimal("1.30"));
225	                }
226	                if (Boolean.TRUE.equals(context.isWithContrast())) {
227	                    adjusted = adjusted.multiply(new BigDecimal("1.45"));
228	                }
229	                if (context.getNumberOfViews() != null) {
230	                    int views = context.getNumberOfViews();
231	                    if (views == 1) {
232	                        adjusted = adjusted.multiply(new BigDecimal("0.80"));
233	                    } else if (views == 2) {
234	                    } else if (views >= 3) {
235	                        adjusted = adjusted.multiply(new BigDecimal("1.20"));
236	                    }
237	                }
238	                if (Boolean.TRUE.equals(context.isStatOrder())) {
239	                    adjusted = adjusted.multiply(new BigDecimal("1.35"));
240	                }
241	                break;
242	
243	            case "LABORATORY":
244	                if (Boolean.TRUE.equals(context.isStatOrder())) {
245	                    adjusted = adjusted.multiply(new BigDecimal("1.40"));
246	                }
247	                if (Boolean.TRUE.equals(context.isFastingRequired()) && Boolean.TRUE.equals(context.isFastingCompleted())) {
248	                    adjusted = adjusted.multiply(new BigDecimal("1.05"));
249	                }
250	                if (context.getLabPanelSize() != null) {
251	                    int panelSize = context.getLabPanelSize();
252	                    if (panelSize >= 5) {
253	                        adjusted = adjusted.multiply(new BigDecimal("0.90"));
254	                    } else if (panelSize >= 10) {
255	                        adjusted = adjusted.multiply(new BigDecimal("0.85"));
256	                    }
257	                }
258	                break;
259	
260	            case "TELEHEALTH":
261	                if (context.getTelehealthPlatform() != null) {
262	                    switch (context.getTelehealthPlatform()) {
263	                        case "VIDEO":
264	                            break;
265	                        case "PHONE":
266	                            adjusted = adjusted.multiply(new BigDecimal("0.85"));
267	                            break;
268	                        case "CHAT":
269	                            adjusted = adjusted.multiply(new BigDecimal("0.70"));
270	                            break;
271	                    }
272	                }
273	                if (context.getDuration() != null) {
274	                    int minutes = context.getDuration();
275	                    if (minutes < 15) {
276	                        adjusted = adjusted.multiply(new BigDecimal("0.75"));
277	                    } else if (minutes > 45) {
278	                        adjusted = adjusted.multiply(new BigDecimal("1.25"));
279	                    } else if (minutes > 60) {
280	                        adjusted = adjusted.multiply(new BigDecimal("1.50"));
281	                    }
282	                }
283	                break;
284	
285	            case "PROCEDURE":
286	                if (Boolean.TRUE.equals(context.requiresSedation())) {
287	                    adjusted = adjusted.multiply(new BigDecimal("1.40"));
288	                }
289	                if (Boolean.TRUE.equals(context.requiresAssistant())) {
290	                    adjusted = adjusted.multiply(new BigDecimal("1.20"));
291	                }
292	                if (context.getAnesthesiaType() != null) {
293	                    switch (context.getAnesthesiaType()) {
294	                        case "LOCAL":
295	                            adjusted = adjusted.multiply(new BigDecimal("1.10"));
296	                            break;
297	                        case "REGIONAL":
298	                            adjusted = adjusted.multiply(new BigDecimal("1.30"));
299	                            break;
300	                        case "GENERAL":
301	                            adjusted = adjusted.multiply(new BigDecimal("1.60"));
302	                            break;
303	                    }
304	                }
305	                break;
306	
307	            default:
308	                log.debug("No specific adjustments for family: {}", family);
309	        }
310	
311	        return adjusted;
312	    }
